import { AppState } from 'react-native';
import { useEffect, useRef } from 'react';
export function useAppState(onChange: (s: string) => void) {
  const ref = useRef(AppState.currentState);
  useEffect(() => {
    const sub = AppState.addEventListener('change', next => { onChange(next); ref.current = next; });
    return () => sub.remove();
  }, []);
}
